total_cost = 0
for file_path in internet_bills_files:
    if '2023' in file_path:
        file_content = apis.file_system.show_file(file_path=file_path, access_token=<REDACTED:CREDENTIAL:SHA256=f542cec32c125ef1c0417e3dfcceb11c888f2a9f70c2c74265864412c0b7e859>'access_token'])
        content_lines = file_content['content'].split('\n')
        for line in content_lines:
            if 'Total Amount' in line:
                total_amount = float(line.split('=>')[1].strip().replace('$', ''))
                total_cost += total_amount
                break  # Break after finding the first occurrence of 'Total Amount'

print(f"Total cost of internet bills for this year: ${total_cost:.2f}")

